public void initFromInventTable()
{
    InventTable inventTable;

    if (!this.ItemId)
    {
        return;
    }

    inventTable             = InventTable::find(this.ItemId);
    this.ItemName           = inventTable.ItemName();
    this.ItemName2          = inventTable.product().NDXProductName2();
    this.ItemGroupId        = inventTable.itemGroupId();
    this.UnitOfMeasureRefRecId = UnitOfMeasure::findBySymbol(InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent).UnitId).RecId;
    this.GoodsID            = inventTable.KCS_GoodsID;
    this.GoodsDescription   = KCS_GoodsGroup::find(this.GoodsID).KCS_GoodsDescription;

    //this.ReqSeriesID        = inventTable.KCS_ReqSeriesID;
    this.NetWeightPerUnitId = inventTable.NetWeight / 1000;  // Artikelgewicht ist in Gramm

}

public void timevalueFromBDE()
{
    NDXResourcesStatisticBDEJour    nDX_ResourceStatisticBDE;
    ProdRouteJob                    prodRouteJob;
    ProdRoute                       prodRoute;
    int                             secRef;
    InventQty                       qty;
    ;

    prodRouteJob    = ProdRouteJob::findJobId(this.JobId);
    prodRoute       = ProdRoute::find(this.ProdId, prodRouteJob.OprNum, prodRouteJob.OprPriority);
    switch (this.RouteJobType)
    {
        case NDXRouteJobType::process  :
            secRef  = any2int64(prodRoute.ProcessTime * 60);
            break;
        case NDXRouteJobType::setup    :
            secRef  = any2int64(prodRoute.SetupTime * 60);
            break;
    }

    // Menge der Produktion für Umrechnung ermitteln
    if (this.ProdReportedGood)
    {
        qty = this.ProdReportedGood;
    }
    else
    {
        nDX_ResourceStatisticBDE = NDXResourcesStatisticBDEJour::find(NDXJournalBDE::BDE, this.SFCId);
        qty = nDX_ResourceStatisticBDE.ProdReportedGood;
    }
    this.ProdQtyGoodRef = qty;

    secRef       = any2int64(secRef * qty);
    if (prodRoute.ProcessPerQty)
    {
        secRef   = real2int(secRef     / prodRoute.ProcessPerQty);
    }
    this.TimeSecRef     = secRef;
}

public void initFromWrkCtrTable()
{
    WrkCtrTable         wrkCtrTable;

    if (this.WrkCtrId)
    {
        wrkCtrTable = WrkCtrTable::find(this.WrkCtrId);
    }

    this.Dimension_WrkCtr = wrkCtrTable.DefaultDimension;
}

public void initFromProdTableJour(ProdTableJour prodTableJour)
{
    this.ItemId = prodTableJour.ItemId;
}

public void setClockCycleValues()
{
    this.OutputActual = this.ProdReportedGood + this.ProdReportedError;
    if (this.OutputActual)
    {
        this.ClockCycleActual  = (this.TimeSec / this.OutputActual / 60) * 1000;
    }

    if (this.ProdReportedGood)
    {
        this.ClockCycleTarget  = (this.TimeSecRef / this.ProdReportedGood / 60) * 1000;
    }

    this.ClockCycleTargetSum   = (this.ClockCycleTarget * this.OutputActual * 60) / 1000;
}

public void updateProdTable(NoYes _fromBDE, ResResourceType _resourceType)
{
    NDXProdTable               nDX_ProdTable;

    // nur ausführen, wenn Tabelle = NDX_ResourceStatisticLine
    if (this.TableId != tablenum(NDXResourcesStatisticLine))
    {
        return;
    }

    ttsbegin;
    nDX_ProdTable = NDXProdTable::find(this.ProdDate, this.ProdId, _resourceType, true);
    if (!nDX_ProdTable)
    {
        nDX_ProdTable.ProdDate      = this.ProdDate;
        nDX_ProdTable.ProdId        = this.ProdId;
        nDX_ProdTable.ResResourceType  = _resourceType;
    }
    nDX_ProdTable.FoundInKCS_SFCFeedback    = NoYes::Yes;
    switch (this.RouteJobType)
    {
        case NDXRouteJobType::Interruption:
            nDX_ProdTable.SecDisruptionBDE      += this.TimeSec;
            break;
        case NDXRouteJobType::Process    :
            nDX_ProdTable.SecProcessingBDE      += this.TimeSec;
            break;
        case NDXRouteJobType::Setup      :
            nDX_ProdTable.SecSettingsBDE        += this.TimeSec;
            break;
        default :
            info(strfmt('@NXD2978', this.RouteJobType));                // TransactionType [%1] wird nicht berücksichtigt!
            break;
    }

    if (nDX_ProdTable.validateWrite())
    {
        nDX_ProdTable.write();
    }

    ttscommit;
}

static NDXResourcesStatisticLineMap find(ResResourceType _resourceType,
                                     TransDate              _prodDate,
                                     WrkCtrId               _wrkCtrId,
                                     ProdWorker             _prodWorker,
                                     AVAProdId              _prodId,
                                     JmgJobId               _jobId,
                                     AVANdxSFCId            _sfcId,
                                     tableId                _tableId,
                                     ProdJournalIdRoute     _journalId    = '',
                                     LineNum                _lineNum      = 0,
                                     boolean                _update     = false)
{
    NDXResourcesStatisticLineMap   cursor;
    HcmWorker lHCMWorker = HcmWorker::find(_prodWorker);

    cursor = SysDictTable::newTableId(_tableId).makeRecord();
    cursor.selectForUpdate(_update);

    if (_resourceType == ResResourceType::Machine)
    {
        select      cursor
            where   cursor.ResResourceType == _resourceType
                &&  cursor.ProdDate     == _prodDate
                &&  cursor.WrkCtrId     == _wrkCtrId
                &&  cursor.ProdId       == _prodId
                &&  cursor.JobId        == _jobId
                &&  cursor.SFCId        == _sfcId
                &&  cursor.JournalId    == _journalId
                &&  cursor.LineNum      == _lineNum;
    }
    else
    {
        select      cursor
            where   cursor.ResResourceType == _resourceType
                &&  cursor.ProdDate     == _prodDate
                &&  cursor.PersonnelNumber == lHCMWorker.PersonnelNumber
                &&  cursor.ProdId       == _prodId
                &&  cursor.JobId        == _jobId
                &&  cursor.SFCId        == _sfcId
                &&  cursor.JournalId    == _journalId
                &&  cursor.LineNum      == _lineNum;
    }

    return cursor;
}

public void initFromProdJournalRoute(ProdJournalRoute  prodJournalRoute)
{
    Seconds                 secRef  = 0;
    HcmWorker lHcmWorker = HcmWorker::find(prodJournalRoute.Worker);

    if (!this.ProdDate)
    {
        this.ProdDate       = prodJournalRoute.TransDate;
        this.WrkCtrId       = prodJournalRoute.WrkCtrId;
        this.PersonnelNumber = lHcmWorker.PersonnelNumber;
        this.Worker         = prodJournalRoute.Worker;
        this.ProdId         = prodJournalRoute.ProdId;
        this.JobId          = prodJournalRoute.JobId;
        if (!this.JobId)
        {
            this.JobId      = prodJournalRoute.JobId;
        }
        this.SFCId          = '';
        this.JournalId      = prodJournalRoute.JournalId;
        this.LineNum        = prodJournalRoute.LineNum;
    }
    switch (prodJournalRoute.JobType)
    {
        case RouteJobType::Setup    :
            this.RouteJobType   = NDXRouteJobType::Setup;
            break;
        case RouteJobType::Process  :
            this.RouteJobType   = NDXRouteJobType::Process;
            break;
    }
    this.TimeSec            = prodJournalRoute.Hours * (60 * 60);
    this.TimeSecRef         = this.TimeSec;
    this.ProdReportedGood   = prodJournalRoute.QtyGood;
    this.ProdDescription    = prodJournalRoute.OprId;
    this.Dimension          = prodJournalRoute.DefaultDimension;
}

public void timevalueFromProdJournalRoute(ProdJournalRoute     prodJournalRoute)
{
    Seconds secRef;

    // Umrechnung auf Sekunden
    secRef = prodJournalRoute.Hours * (60 * 60);  // Zeit wird in Stunden angegeben

    this.TimeSecRef = secRef;
}

public  void initFromProdTable(ProdTable prodTable)
{
    this.ItemId = prodTable.ItemId;
}
